INSERT INTO `requirement_types` (`facility_id`, `name`, `interval_months`, `builtin_key`, `sort_order`) SELECT `id`, 'Erstuntersuchung (§ 32 JArbSchG)', NULL, 'youth_initial', (SELECT COALESCE(MAX(`sort_order`), -1) + 1 FROM `requirement_types` WHERE `requirement_types`.`facility_id` = `facilities`.`id`) FROM `facilities`;--> statement-breakpoint
INSERT INTO `requirement_types` (`facility_id`, `name`, `interval_months`, `builtin_key`, `sort_order`) SELECT `id`, 'Nachuntersuchung (§ 33 JArbSchG)', NULL, 'youth_followup', (SELECT COALESCE(MAX(`sort_order`), -1) + 1 FROM `requirement_types` WHERE `requirement_types`.`facility_id` = `facilities`.`id`) FROM `facilities`;
